  'calc.noMatch': 'No matches among the game’s words',
  'calc.space': 'space',
  'calc.backspace': 'delete',
  'calc.methods': 'Other ways of counting',
  'calc.methodsSub': 'The commentators count words not only in the usual gematria. Here is this word in every way:',
  'method.standard': 'Usual gematria (mispar hechrechi)',
  'method.standard.rule': 'א = 1 … ת = 400; final letters equal the regular ones.',
  'method.gadol': 'Great number (mispar gadol)',
  'method.gadol.rule': 'Final letters go on counting: ך 500, ם 600, ן 700, ף 800, ץ 900.',
  'method.katan': 'Small gematria (mispar katan)',
  'method.katan.rule': 'The letter’s value without zeros: י = 1, כ = 2 … ק = 1, ת = 4.',
  'method.siduri': 'Ordinal number (mispar siduri)',
  'method.siduri.rule': 'The letter’s place in the alphabet: א = 1, ב = 2 … ת = 22.',
  'method.kadmi': 'Cumulative number (mispar ha-kadmi)',
  'method.kadmi.rule': 'The sum of all letters from א up to this one: ב = 1 + 2 = 3, ג = 6.',
  'method.milui': 'Full spelling (milui)',
  'method.milui.rule': 'Every letter is written out by its name: א = אלף = 111.',
  'method.neelam': 'Hidden part (ne’elam)',
  'method.neelam.rule': 'The letter’s name without the letter itself: אלף − א = לף = 110.',
  'method.atbash': 'Atbash (א״ת ב״ש)',
  'method.atbash.rule': 'Letters are swapped like a mirror: א ↔ ת, ב ↔ ש, ג ↔ ר…',
  'method.albam': 'Albam (א״ל ב״ם)',
  'method.albam.rule': 'The alphabet is split in two halves: א ↔ ל, ב ↔ מ, ג ↔ נ…',
  'method.kolel': 'With the kolel (im ha-kolel)',
  'method.kolel.rule': 'Add 1 to the gematria — the word itself as a whole (sometimes the number of words or letters).',
  'method.katanMispari': 'Sum of digits (katan mispari)',
  'method.katanMispari.rule': 'The digits are added up until one is left: 441 → 4 + 4 + 1 = 9.',
  'method.riboa': '“Square” (ribua)',
  'method.riboa.rule': 'Add up the growing beginnings of the word: אמת = א + אמ + אמת.',

  'helper.title': 'Helper',
  'helper.intro': 'I’ll break the gematria of any word into steps, show the lesson’s primary sources and answer common questions.',
